#include "communication/scheduler.h"
#include "communication/sync.h"

class Logger; // host/logger.h

/// @brief Result of one time-synchronization exchange, in time units.
/// @details `units` is the negative power of ten the values are
///          expressed in (milliseconds == 3). `path_delay_units` is this
///          exchange's measured mean one-way path delay (>= 0);
///          `offset_units` is the RT's recommended offset (the value the
///          RT smoothed and applied to its own clock): the BC clock minus
///          the RT clock, added to an RT timestamp to express it on the BC
///          clock (signed: positive when the BC clock leads the RT clock).
///          `reload_ticks` is the last SysTick reload programmed by sync_adjust()
///          (0 until the first sync_adjust() call).
struct SyncMeasurement {
    double   path_delay_units;
    double   offset_units;
    uint32_t reload_ticks;
    uint8_t  units;
};

/// @brief Result of one SYNC_ADJUST: the skew the RT averaged over the
///        preceding telemetry phase and the SysTick reload it then programmed.
/// @details `avg_skew_ppb` is the BC-vs-RT skew in parts-per-billion (positive
///          when the BC gains on the RT, i.e. the RT runs slow). `reload_ticks`
///          is the full tick count now programmed; it moves a fraction of the
///          way toward the rate that cancels the skew and stays within +/-10%
///          of nominal, so the clocks lock over several telemetry/adjust cycles.
struct SyncAdjustResult {
    int32_t  avg_skew_ppb;
    uint32_t reload_ticks;
};

/// @file rt_client.h
/// @brief Auto-generated host-side client for this RT's API.
/// @details
/// Every method is blocking: it submits a Request to the BusController
/// and polls bc.tick() until the completion callback fires or the
/// outer watchdog expires. Not thread-safe: use one RtClient per
/// thread, or add external locking.

/// @brief Translate a Status value into a short human-readable name.
/// @param s Any Status value.
/// @return A pointer to a static string ("Ok", "Timeout", ...).
///         Returns "Unknown" for unrecognized values.
char const* status_to_string(Status s);

/// @brief Translate a FaultDomain tag into a short human-readable name.
/// @param d Any FaultDomain value (byte 0 of a fault payload).
/// @return A pointer to a static string ("Protocol", "Hal", "App").
///         Returns "Unknown" for unrecognized values.
char const* fault_domain_to_string(FaultDomain d);

/// @brief Decode a (sub-address, opcode) pair to a human-readable
///        operation name for logging.
/// @param sub_address Routed sub-address of the command.
/// @param opcode First payload byte of the command.
/// @return A static string; "UNKNOWN" for unrecognized pairs.
char const* op_name(uint8_t sub_address, uint8_t opcode);

/// @brief Resolve a routed sub-address to its human-readable name
///        (the instance name from the manifest) for logging.
/// @param sub_address Routed sub-address.
/// @return A static string; "UNKNOWN" for unrecognized sub-addresses.
char const* sub_address_name(uint8_t sub_address);

