/// @brief Host observer that logs every failed BC transaction attempt as a
///        WARNING, including attempts later recovered by the single automatic
///        retry (which would otherwise leave no trace but the fault counter).
/// @details Injected into the RtClient's BusController; writes through the
///          same Logger as the rest of the client.
class LoggerFaultObserver : public IBusFaultObserver {
    public:

    explicit LoggerFaultObserver(Logger& log) : m_log(log) {}

    void on_fault(uint8_t sub_addr, Status status, bool will_retry) override;

    private:

    Logger& m_log;
};

class RtClient {
    private:

    // Declared first so the per-peripheral nested members below can
    // bind to them in their initializer list. C++ initializes class
    // members in declaration order, not initializer-list order.
    // m_fault_observer precedes m_bc: the BusController is constructed
    // with a pointer to it, so the observer must already exist.
    LoggerFaultObserver m_fault_observer;
    BusController m_bc;
    IClock&       m_clock;
    Logger&       m_log;

    // Latest time-sync state (see sync_once). `m_offset` is the RT's
    // recommended offset, smoothed and applied on the RT side and stored
    // here as-is; `m_path_delay` is the latest measured path delay.
    bool     m_have_sync    = false;
    double   m_offset       = 0.0;
    double   m_path_delay   = 0.0;
    uint32_t m_reload_ticks = 0;
    uint8_t  m_sync_units   = static_cast<uint8_t>(TimeUnits::Millisecond);

    public:

    /// @brief Construct; binds to the given transport, clock, and
    ///        logger. All three references must outlive this RtClient.
    RtClient(IFrameTransport& transport, IClock& clock, Logger& log);

    /// @brief System handler: read the RT's 32-bit API fingerprint.
    Status get_api_fingerprint(uint32_t& fingerprint_out);

    /// @brief Universal command: read the per-service API hash of @p sub_address
    ///        (opcode 0x00, GET_SERVICE_HASH). Works for any registered
    ///        sub-address, including the system handler.
    Status get_service_hash(uint8_t sub_address, uint32_t& hash_out);

    /// @brief System handler: read the count of registered devices.
    Status get_device_count(uint16_t& count_out);

    /// @brief System handler: read the RT's HAL millisecond uptime
    ///        counter (HAL_GetTick).
    Status get_sys_tick(uint32_t& ticks_out);

    /// @brief System handler: read the ARM core device ID and
    ///        revision ID (HAL_GetDEVID / HAL_GetREVID).
    Status get_core_device_id(uint32_t& devid_out, uint32_t& revid_out);

    /// @brief System handler: read the 96-bit CPU unique ID words 0..2
    ///        (HAL_GetUIDw0/1/2).
    Status get_cpu_id(uint32_t& uid0_out, uint32_t& uid1_out, uint32_t& uid2_out);

    /// @brief System handler: read the RT's running count of inbound messages
    ///        that failed due to a timeout or a CRC / malformed-frame error.
    Status get_message_fault_counter(uint32_t& count_out);

    /// @brief System handler: trigger a soft reset of the RT.
    ///        The RT sends a write-ack then resets via HAL_NVIC_SystemReset.
    Status soft_reset();

    /// @brief System handler: read @p len bytes of RT memory starting at
    ///        @p address into @p data_out. @p len must not exceed the RT's
    ///        max response frame (kMaxPayloadBytes); the RT also rejects an
    ///        address+length that wraps past the 32-bit range.
    Status read_memory(uint32_t address, uint16_t len, uint8_t* data_out);

    /// @brief Convenience: read fingerprint and compare to the
    ///        compile-time kApiFingerprint. Returns Status::Ok
    ///        on a match, ::HandlerError on mismatch, or the
    ///        original error if the read itself failed.
    Status verify_fingerprint();

    /// @brief Read each registered sub-address's per-service hash and compare
    ///        it to the expected compile-time kServiceHash<Kind> constant.
    /// @details Use after verify_fingerprint() fails to localize which device
    ///          handler(s) diverged: each mismatch is logged. Returns Status::Ok
    ///          only if every sub-address matched; otherwise ::HandlerError
    ///          (or the first read error encountered).
    Status verify_service_hashes();

    /// @brief Run one Cristian-style time-synchronization exchange with the
    ///        RT (SYNC_PROBE / SYNC_FINAL on sub-address 1).
    /// @details
    /// On success the RT returns its recommended clock offset -- the value
    /// it smoothed and applied to its own clock -- which is stored as-is in
    /// clock_offset_units() (no BC-side filtering). The RT seeds its filter
    /// on the first exchange and settles it over later ones, so call this
    /// repeatedly to let the RT average out bus jitter. path_delay_units()
    /// is the latest measured value.
    /// @param raw_out Optional; receives this exchange's reported values
    ///        (recommended offset, measured path delay, units).
    /// @return Status::Ok on a full exchange, else the first failing step's status.
    Status sync_once(SyncMeasurement* raw_out = nullptr);

    /// @brief True once at least one sync_once() has succeeded.
    bool has_sync() const { return m_have_sync; }

    /// @brief The RT's recommended clock offset (BC clock minus RT clock),
    ///        in time units (signed) -- smoothed and applied on the RT side.
    ///        Add to an RT timestamp to express it on the BC clock.
    ///        Meaningful only once has_sync() is true.
    double clock_offset_units() const { return m_offset; }

    /// @brief Latest measured mean one-way path delay, in time units.
    ///        Meaningful only once has_sync() is true.
    double path_delay_units() const { return m_path_delay; }

    /// @brief SysTick reload (full tick count) the RT last programmed to
    ///        discipline its tick rate onto the BC. 0 until has_sync().
    uint32_t reload_ticks() const { return m_reload_ticks; }

    /// @brief Time-unit code the sync estimates are expressed in
    ///        (negative power of ten; milliseconds == 3).
    uint8_t sync_units() const { return m_sync_units; }

    /// @brief Apply one smoothed SysTick-reload adjustment on the RT from the
    ///        skew averaged over the preceding telemetry phase (SYNC_ADJUST on
    ///        sub-address 1).
    /// @details Run a batch of sync_once() exchanges (the telemetry phase) to let
    /// the RT's estimator average the BC-vs-RT skew, then call this once to apply a
    /// single bounded, partial-step reload change toward the rate that cancels it.
    /// Repeat (telemetry phase, then sync_adjust) -- the clocks lock over several
    /// cycles because each step is smoothed and clamped to +/-10% of nominal.
    /// @param out Optional; receives the averaged skew used and the reload now
    ///        programmed (also reflected in reload_ticks()).
    /// @return Status::Ok on success, else the transaction's failing status.
    Status sync_adjust(SyncAdjustResult* out = nullptr);

    /// @brief Local read: running count of bus faults the BC itself has
    ///        detected (timeouts + CRC / malformed-frame errors on the BC
    ///        side). Does not send any bus transaction.
    uint32_t bc_fault_count() const { return m_bc.fault_count(); }

    /// @brief Sub-address 2 (MyAdc).
    AdcClient adc_hadc1_ch1;

    /// @brief Sub-address 3 (CAN1).
    CanClient can_hcan1;

    /// @brief Sub-address 4 (BOOT1).
    GpioInputClient gpio_PB2;

    /// @brief Sub-address 5 (OTG_FS_OverCurrent).
    GpioInputClient gpio_PD5;

    /// @brief Sub-address 6 (OTG_FS_PowerSwitchOn).
    GpioOutputClient gpio_PC0;

    /// @brief Sub-address 7 (Audio_RST [CS43L22_RESET]).
    GpioOutputClient gpio_PD4;

    /// @brief Sub-address 7 (LD4 [Green Led]).
    GpioOutputClient gpio_PD12;

    /// @brief Sub-address 7 (LD3 [Orange Led]).
    GpioOutputClient gpio_PD13;

    /// @brief Sub-address 7 (LD5 [Red Led]).
    GpioOutputClient gpio_PD14;

    /// @brief Sub-address 7 (LD6 [Blue Led]).
    GpioOutputClient gpio_PD15;

    /// @brief Sub-address 8 (CS_I2C/SPI [LIS302DL_CS_I2C/SPI]).
    GpioOutputClient gpio_PE3;

    /// @brief Sub-address 9 (I2C1).
    I2cClient i2c_hi2c1;

    /// @brief Sub-address 10 (RTC).
    RtcClient rtc;

    /// @brief Sub-address 11 (SPI1).
    SpiClient spi_hspi1;

};

#endif // RT_CLIENT_H
